#!/usr/bin/env python3
"""UK Retail Fuel Price Trend Analysis — Report Generator"""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import seaborn as sns
from io import BytesIO
import base64
from datetime import datetime
import warnings
warnings.filterwarnings('ignore')

# ── Style ──────────────────────────────────────────────────────────────────
sns.set_style("whitegrid")
plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.sans-serif': ['DejaVu Sans', 'Arial', 'Helvetica'],
    'axes.titlesize': 13,
    'axes.labelsize': 11,
    'xtick.labelsize': 9,
    'ytick.labelsize': 9,
    'legend.fontsize': 9,
    'figure.dpi': 120,
    'savefig.dpi': 120,
    'savefig.bbox': 'tight',
    'savefig.pad_inches': 0.15,
})

# Colour palette — professional, accessible
PALETTE = {
    'E10': '#2166ac',
    'B7_STANDARD': '#b2182b',
    'E5': '#4daf4a',
    'B7_PREMIUM': '#ff7f00',
    'B10': '#984ea3',
}
DEFAULT_COL = '#6baed6'

def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=120, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
    return f'data:image/png;base64,{b64}'

# ── Load Data ──────────────────────────────────────────────────────────────
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv')

# Parse timestamps
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)

# Compute update lag in hours
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# Basic cleaning: remove negative lags (source_updated_at should be <= recorded_at)
# Flag but keep for analysis
df['negative_lag'] = df['update_lag_hours'] < 0

total_rows = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = sorted(df['fuel_type'].unique())
date_min = df['recorded_at'].min()
date_max = df['recorded_at'].max()
negative_lag_count = df['negative_lag'].sum()

print(f"  Rows: {total_rows:,}")
print(f"  Unique stations: {unique_stations:,}")
print(f"  Fuel types: {fuel_types}")
print(f"  Date range: {date_min} to {date_max}")
print(f"  Negative lags: {negative_lag_count}")

# ── Section 1: Dataset Overview ────────────────────────────────────────────
print("\n=== Section 1: Dataset Overview ===")

# Records per fuel type
fuel_counts = df['fuel_type'].value_counts()
print(fuel_counts)

# Date range by fuel type
date_range_by_fuel = df.groupby('fuel_type').agg(
    earliest_record=('recorded_at', 'min'),
    latest_record=('recorded_at', 'max')
).reset_index()

# Stations per fuel type
stations_per_fuel = df.groupby('fuel_type')['node_id'].nunique().reset_index()
stations_per_fuel.columns = ['fuel_type', 'station_count']

# ── Section 2: Price Distribution by Fuel Type ─────────────────────────────
print("\n=== Section 2: Price Distribution ===")

price_stats = df.groupby('fuel_type')['price_pence'].agg(
    count='count',
    mean='mean',
    median='median',
    std='std',
    min='min',
    max='max',
    q25=lambda x: x.quantile(0.25),
    q75=lambda x: x.quantile(0.75),
    iqr=lambda x: x.quantile(0.75) - x.quantile(0.25)
).reset_index()
price_stats['range'] = price_stats['max'] - price_stats['min']
price_stats['mean'] = price_stats['mean'].round(1)
price_stats['median'] = price_stats['median'].round(1)
price_stats['std'] = price_stats['std'].round(1)
price_stats['iqr'] = price_stats['iqr'].round(1)
price_stats['range'] = price_stats['range'].round(1)
print(price_stats.to_string(index=False))

# ── Charts ─────────────────────────────────────────────────────────────────
print("\nGenerating charts...")
charts = {}

# Chart 1: Violin plot — price distribution by fuel type
fig, ax = plt.subplots(figsize=(10, 5.5))
order = ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM', 'B10']
available = [f for f in order if f in df['fuel_type'].unique()]
parts = ax.violinplot(
    [df[df['fuel_type']==f]['price_pence'].dropna().values for f in available],
    positions=range(len(available)),
    widths=0.7,
    showmeans=True,
    showmedians=True
)
for i, pc in enumerate(parts['bodies']):
    pc.set_facecolor(PALETTE.get(available[i], DEFAULT_COL))
    pc.set_alpha(0.75)
for partname in ('cbars', 'cmins', 'cmaxes', 'cmeans', 'cmedians'):
    if partname in parts:
        parts[partname].set_color('#333333')
        parts[partname].set_linewidth(1.2)
ax.set_xticks(range(len(available)))
ax.set_xticklabels(available, fontsize=10)
ax.set_ylabel('Price (pence per litre)', fontsize=11)
ax.set_title('Price Distribution by Fuel Type — February–April 2026', fontsize=13, fontweight='bold')
ax.grid(axis='y', alpha=0.3)
charts['violin'] = fig_to_b64(fig)

# Chart 2: Box plot — price distribution
fig, ax = plt.subplots(figsize=(10, 5.5))
box_data = [df[df['fuel_type']==f]['price_pence'].dropna().values for f in available]
bp = ax.boxplot(box_data, positions=range(len(available)), widths=0.55,
                patch_artist=True, showfliers=True, flierprops=dict(marker='o', markersize=3, alpha=0.4))
for i, patch in enumerate(bp['boxes']):
    patch.set_facecolor(PALETTE.get(available[i], DEFAULT_COL))
    patch.set_alpha(0.8)
for median in bp['medians']:
    median.set_color('#222222')
    median.set_linewidth(2)
ax.set_xticks(range(len(available)))
ax.set_xticklabels(available, fontsize=10)
ax.set_ylabel('Price (pence per litre)', fontsize=11)
ax.set_title('Price Distribution by Fuel Type (Box Plot)', fontsize=13, fontweight='bold')
ax.grid(axis='y', alpha=0.3)
charts['boxplot'] = fig_to_b64(fig)

# Chart 3: Histogram / KDE — overlay by fuel type
fig, ax = plt.subplots(figsize=(10, 5.5))
for ft in available:
    subset = df[df['fuel_type']==ft]['price_pence'].dropna()
    sns.kdeplot(data=subset, ax=ax, label=ft, color=PALETTE.get(ft, DEFAULT_COL),
                linewidth=2.2, fill=True, alpha=0.12)
ax.set_xlabel('Price (pence per litre)', fontsize=11)
ax.set_ylabel('Density', fontsize=11)
ax.set_title('Price Density by Fuel Type', fontsize=13, fontweight='bold')
ax.legend(title='Fuel Type', fontsize=9)
ax.grid(axis='y', alpha=0.3)
charts['kde'] = fig_to_b64(fig)

# Chart 4: Mean price bar chart with error bars (std dev)
fig, ax = plt.subplots(figsize=(9, 5))
stats_plot = df.groupby('fuel_type')['price_pence'].agg(['mean', 'std']).reindex(available)
bars = ax.bar(range(len(available)), stats_plot['mean'], yerr=stats_plot['std'],
              color=[PALETTE.get(f, DEFAULT_COL) for f in available],
              edgecolor='white', linewidth=0.8, capsize=6, width=0.55)
for i, (bar, val) in enumerate(zip(bars, stats_plot['mean'])):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + stats_plot['std'].iloc[i] + 1,
            f'{val:.1f}p', ha='center', fontsize=10, fontweight='bold')
ax.set_xticks(range(len(available)))
ax.set_xticklabels(available, fontsize=10)
ax.set_ylabel('Mean Price (pence per litre)', fontsize=11)
ax.set_title('Mean Price by Fuel Type (±1 Std Dev)', fontsize=13, fontweight='bold')
ax.grid(axis='y', alpha=0.3)
charts['mean_bar'] = fig_to_b64(fig)

# Chart 5: Price spread — IQR and Range comparison
fig, ax = plt.subplots(figsize=(10, 5))
x = np.arange(len(available))
width = 0.35
iqr_vals = [price_stats[price_stats['fuel_type']==f]['iqr'].values[0] if f in price_stats['fuel_type'].values else 0 for f in available]
range_vals = [price_stats[price_stats['fuel_type']==f]['range'].values[0] if f in price_stats['fuel_type'].values else 0 for f in available]
bars1 = ax.bar(x - width/2, range_vals, width, label='Max − Min Range',
               color='#fc8d59', edgecolor='white', linewidth=0.6)
bars2 = ax.bar(x + width/2, iqr_vals, width, label='Interquartile Range (IQR)',
               color='#91bfdb', edgecolor='white', linewidth=0.6)
for bar, val in zip(bars1, range_vals):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.3,
            f'{val:.1f}p', ha='center', fontsize=8.5, fontweight='bold')
for bar, val in zip(bars2, iqr_vals):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.3,
            f'{val:.1f}p', ha='center', fontsize=8.5, fontweight='bold')
ax.set_xticks(x)
ax.set_xticklabels(available, fontsize=10)
ax.set_ylabel('Price Spread (pence per litre)', fontsize=11)
ax.set_title('Price Spread by Fuel Type: Range vs IQR', fontsize=13, fontweight='bold')
ax.legend(fontsize=9)
ax.grid(axis='y', alpha=0.3)
charts['spread'] = fig_to_b64(fig)

# Chart 6: Update lag histogram
fig, ax = plt.subplots(figsize=(10, 5))
lag_data = df[df['update_lag_hours'] >= 0]['update_lag_hours']
# Cap extreme outliers for display
lag_cap = lag_data.quantile(0.99)
lag_display = lag_data.clip(upper=lag_cap)
ax.hist(lag_display, bins=80, color='#6baed6', edgecolor='white', linewidth=0.3, alpha=0.85)
ax.axvline(lag_data.median(), color='#b2182b', linestyle='--', linewidth=2,
           label=f'Median: {lag_data.median():.1f} hours')
ax.axvline(lag_data.quantile(0.9), color='#ff7f00', linestyle='--', linewidth=1.5,
           label=f'90th %ile: {lag_data.quantile(0.9):.1f} hours')
ax.set_xlabel('Update Lag (hours)', fontsize=11)
ax.set_ylabel('Number of Records', fontsize=11)
ax.set_title('Distribution of Retailer Update Lag', fontsize=13, fontweight='bold')
ax.legend(fontsize=9)
ax.grid(axis='y', alpha=0.3)
charts['lag_hist'] = fig_to_b64(fig)

# Chart 7: Update lag by fuel type (box plot)
fig, ax = plt.subplots(figsize=(10, 5.5))
lag_by_fuel = [df[(df['fuel_type']==f) & (df['update_lag_hours']>=0)]['update_lag_hours'].clip(upper=lag_cap).values for f in available]
bp = ax.boxplot(lag_by_fuel, positions=range(len(available)), widths=0.55,
                patch_artist=True, showfliers=True, flierprops=dict(marker='o', markersize=2, alpha=0.3))
for i, patch in enumerate(bp['boxes']):
    patch.set_facecolor(PALETTE.get(available[i], DEFAULT_COL))
    patch.set_alpha(0.8)
for median in bp['medians']:
    median.set_color('#222222')
    median.set_linewidth(2)
ax.set_xticks(range(len(available)))
ax.set_xticklabels(available, fontsize=10)
ax.set_ylabel('Update Lag (hours, capped at 99th %ile)', fontsize=11)
ax.set_title('Update Lag by Fuel Type', fontsize=13, fontweight='bold')
ax.grid(axis='y', alpha=0.3)
charts['lag_by_fuel'] = fig_to_b64(fig)

# Chart 8: Station coverage — fuel types per station
fig, ax = plt.subplots(figsize=(9, 5))
fuels_per_station = df.groupby('node_id')['fuel_type'].nunique()
coverage_counts = fuels_per_station.value_counts().sort_index()
bars = ax.bar(coverage_counts.index.astype(str), coverage_counts.values,
              color='#6baed6', edgecolor='white', linewidth=0.6, width=0.5)
for bar, val in zip(bars, coverage_counts.values):
    ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + max(coverage_counts.values)*0.01,
            f'{val:,}', ha='center', fontsize=10, fontweight='bold')
ax.set_xlabel('Number of Fuel Types Reported', fontsize=11)
ax.set_ylabel('Number of Stations', fontsize=11)
ax.set_title('Station Coverage: Fuel Types per Station', fontsize=13, fontweight='bold')
ax.grid(axis='y', alpha=0.3)
charts['coverage'] = fig_to_b64(fig)

# Chart 9: Records over time, coloured by fuel type
fig, ax = plt.subplots(figsize=(10, 5))
df['recorded_date'] = df['recorded_at'].dt.date
daily_counts = df.groupby(['recorded_date', 'fuel_type']).size().unstack(fill_value=0)
for ft in available:
    if ft in daily_counts.columns:
        ax.plot(daily_counts.index, daily_counts[ft], color=PALETTE.get(ft, DEFAULT_COL),
                linewidth=1.3, label=ft, alpha=0.85)
ax.set_xlabel('Date', fontsize=11)
ax.set_ylabel('Number of Price Records', fontsize=11)
ax.set_title('Daily Price Record Volume by Fuel Type', fontsize=13, fontweight='bold')
ax.legend(fontsize=9)
ax.grid(alpha=0.3)
fig.autofmt_xdate()
charts['daily_records'] = fig_to_b64(fig)

# Chart 10: Scatter — price vs update lag
fig, ax = plt.subplots(figsize=(10, 5.5))
sample = df.sample(min(8000, len(df)), random_state=42)
for ft in available:
    subset = sample[sample['fuel_type']==ft]
    if len(subset) > 0:
        ax.scatter(subset['update_lag_hours'].clip(upper=lag_cap), subset['price_pence'],
                   c=PALETTE.get(ft, DEFAULT_COL), label=ft, alpha=0.4, s=12, edgecolors='none')
ax.set_xlabel('Update Lag (hours, capped)', fontsize=11)
ax.set_ylabel('Price (pence per litre)', fontsize=11)
