        <li><strong>B7_PREMIUM</strong> and <strong>B10</strong> are priced substantially higher and show distinct, narrower distributions consistent with their premium positioning.</li>
    </ul>

    <img class="chart-img" src="''' + charts['boxplot'] + '''" alt="Price Distribution Box Plot">

    <h3>Summary Statistics by Fuel Type</h3>
    <table class="data-table">
        <thead><tr><th>Fuel Type</th><th>Records</th><th>Mean (ppl)</th><th>Median (ppl)</th><th>Std Dev</th><th>Min (ppl)</th><th>Max (ppl)</th><th>IQR</th><th>Range</th></tr></thead>
        <tbody>
'''

for _, row in price_stats.iterrows():
    html += f'''<tr>
        <td style="font-weight:600;">{row['fuel_type']}</td>
        <td>{int(row['count']):,}</td>
        <td>{row['mean']:.1f}</td>
        <td>{row['median']:.1f}</td>
        <td>{row['std']:.1f}</td>
        <td>{row['min']:.1f}</td>
        <td>{row['max']:.1f}</td>
        <td>{row['iqr']:.1f}</td>
        <td>{row['range']:.1f}</td>
